    gpGame->scenarioTowns.clear();
    gpGame->signs.clear();
    gpGame->mines.clear();
    gpGame->generators.clear();
    gpGame->garrisons.clear();
    gpGame->boats.clear();
    gpGame->universities.clear();
    gpGame->creatureBanks.clear();

