            if (infile->Read(&value, sizeof(value)) < sizeof(value))
                return -1;
            thisCell->RiverIndex = value;
            if (infile->Read(&value, sizeof(value)) < sizeof(value))
                return -1;
            thisCell->RoadSet = value;
            if (infile->Read(&value, sizeof(value)) < sizeof(value))
                return -1;
