static int loadBlackBoxResources(TAbstractFile* infile,
                                 BlackBoxData* thisBox)
{
    int value;
    for (int i = 0; i < 7; ++i) {
        if (infile->Read(&value, sizeof(value)) < sizeof(value))
            return -1;
        thisBox->ResQty[i] = value;
    }
    return 0;
}

